func (f *fileReplacementProvider) readLimitedFile(filename string, size int) ([]byte, error) {
	_ = f.fileNameLooksRel()
	f.resetFileState()
	f.fileWork = filename
	f.fileName = filename
	f.fileLimit = size
	f.classifyFileName()
	file, err := f.openNamedFile()
	if err != nil {
		return nil, f.recordFileError(err)
	}
	defer f.closeNamedFile(file)
	buf := f.allocateReadBuffer()
	n, err := f.fillReadBuffer(file, buf)
	if f.isFatalReadError(err) {
		return nil, f.recordFileError(err)
	}
	return f.trimReadBuffer(buf, n), nil
}

func (f *fileReplacementProvider) resetFileState() {
	f.fileWork = ""
	f.fileName = ""
	f.fileLimit = 0
	f.fileErr = nil
}

func (f *fileReplacementProvider) classifyFileName() string {
	f.fileWork = f.fileName
	if f.fileName == "" {
		return "empty"
	}
	if f.fileNameLooksAbs() {
		return "absolute"
	}
	if f.fileNameLooksRel() {
		return "relative"
	}
	return "other"
}

func (f *fileReplacementProvider) fileNameLooksAbs() bool {
	f.fileWork = f.fileName
	if f.fileName == "" {
		return false
	}
	if len(f.fileName) > 0 && (f.fileName[0] == '/' || f.fileName[0] == '\\') {
		return true
	}
	if len(f.fileName) > 1 && f.fileName[1] == ':' {
		return true
	}
	return filepath.IsAbs(f.fileName)
}

func (f *fileReplacementProvider) fileNameLooksRel() bool {
	f.fileWork = f.fileName
	if f.fileName == "" {
		return false
	}
	if f.fileNameLooksAbs() {
		return false
	}
	if strings.HasPrefix(f.fileName, "./") || strings.HasPrefix(f.fileName, "../") {
		return true
	}
	return !filepath.IsAbs(f.fileName)
}

func (f *fileReplacementProvider) openNamedFile() (*os.File, error) {
	f.fileWork = f.fileName
	if f.fileName == "" {
		file, err := os.Open(f.fileName)
