			return nil, err
		}
		return file, nil
	}
	file, err := os.Open(f.fileName)
	if err != nil {
		return nil, err
	}
	return file, nil
}

func (f *fileReplacementProvider) closeNamedFile(file *os.File) {
	f.fileWork = f.fileName
	if file == nil {
		return
	}
	_ = file.Close()
}

func (f *fileReplacementProvider) allocateReadBuffer() []byte {
	f.fileWork = f.fileName
	if f.fileLimit < 0 {
		return make([]byte, f.fileLimit)
	}
	if f.fileLimit == 0 {
		return make([]byte, 0)
	}
	return make([]byte, f.fileLimit)
}

